package com.lrsmotors.app
import android.app.*
import android.content.*
import android.telephony.TelephonyManager
import androidx.core.app.NotificationCompat
class CallReceiver:BroadcastReceiver(){override fun onReceive(c:Context,i:Intent){if(i.action!=TelephonyManager.ACTION_PHONE_STATE_CHANGED)return;val state=i.getStringExtra(TelephonyManager.EXTRA_STATE)?:return;val pref=c.getSharedPreferences("call_state",Context.MODE_PRIVATE);when(state){TelephonyManager.EXTRA_STATE_RINGING,TelephonyManager.EXTRA_STATE_OFFHOOK->pref.edit().putBoolean("active",true).apply();TelephonyManager.EXTRA_STATE_IDLE->if(pref.getBoolean("active",false)){pref.edit().putBoolean("active",false).apply();android.os.Handler(android.os.Looper.getMainLooper()).postDelayed({val call=SimCallResolver.latestForSelectedSim(c,180000L)?:return@postDelayed;val p=LeadStore.normalize(call.phone);if(p.isBlank())return@postDelayed;val pending=pref.getString("pending_followup_call","").orEmpty();if(pending.isNotBlank()&&LeadStore.normalize(pending)==p){LeadStore(c).setAction(p,"DONE");pref.edit().remove("pending_followup_call").apply();return@postDelayed};val nm=c.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager;nm.createNotificationChannel(NotificationChannel("new_calls","New LRS call leads",NotificationManager.IMPORTANCE_HIGH));val open=PendingIntent.getActivity(c,p.hashCode(),Intent(c,MainActivity::class.java).putExtra("after_call_phone",p).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP),PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE);nm.notify(p.hashCode(),NotificationCompat.Builder(c,"new_calls").setSmallIcon(android.R.drawable.sym_action_call).setContentTitle("LRS Motors · Save this caller?").setContentText("$p · tap to select Car/Bike and requirement").setPriority(NotificationCompat.PRIORITY_MAX).setAutoCancel(true).setContentIntent(open).build())},2500)}}}}